# Authored story data; run only to regenerate the bundled JSON.
$chapters = @(
@{title='第1章 消えた名前';speaker='ガルド（戦士）';portrait='ally_warrior';boss='十階の守護者が崩れると、鎧の中から小さな名札が落ちた。ガルドはそれを拾い、指を止める。「俺が守れなかった村の子だ。なぜ、こんな所に……」';reveal='名札に触れると、消えた村の鐘が聞こえた。テオが壁の文字を読む。「塔は死者を呼んでいるんじゃない。地上から奪った記憶を、ここに閉じ込めている」';gald='「俺は元・王都の衛兵だ。盾の傷？ 村の門を守った時についた。……守り切った、とは言ってない」ガルドは笑おうとして、盾の縁を握り直した。';mina='「あなたの名前を、もう一度教えてくれる？」ミナは手帳を開く。「最近、昨日助けた人の名前が思い出せなくなるの。忘れないように書いておきたいんだ」';rina='「足跡が消えてる。風もないのに」リナは冗談をやめ、床に葉を置く。「森で道を見失うより嫌な感じ。私たちが通ったことまで、消そうとしてる」';theo='「この光は星明かりじゃない。記憶が燃える時の色だ」テオは眼鏡を直す。「断言はできないけど……君の胸の欠片も、同じ色をしてる」';topic='鐘の音と消える足跡';banter='リナ「私が先頭。ガルド、足音を小さく」
ガルド「この鎧でか？ 無茶を言うな」
ミナ「でも、聞こえると安心するよ」
テオ「迷子になったら、その足音を目印にしよう」'},
@{title='第2章 届かなかった手紙';speaker='ミナ（僧侶）';portrait='ally_priest';boss='二十階の守護者から、宛先のない手紙が落ちた。『お姉ちゃん、帰ってきて』。ミナの指が震える。「妹の字だ。でも、この手紙を受け取った覚えはない」';reveal='手紙の裏には、塔へ送られた人の名簿があった。妹の名は、その中にある。「死んだと聞かされたの。誰が、私にそう言ったのかな」ミナは手紙をしまう。「今度は、自分で確かめる」';gald='「王都の知らせを信じた。家族は避難した、と。確認もせずにな」ガルドは落ちた封筒を拾う。「紙に書いてあれば正しいなんて、俺は何を守っていたんだろう」';mina='「妹は手紙の最後に、いつも花を描くの」ミナは指で空中に小さな花を描いた。「名前を忘れても、この描き方は忘れない。だから、まだ探せる」';rina='「手紙って、遠くの人に届く小さな矢みたいだね」リナは封筒を乾かす。「私の矢は外さない。この手紙も、最後まで届けたい」';theo='「名簿の人数と、星灯りの数が合う」テオは言葉を選ぶ。「数字として見るのは簡単だ。でも、数字には妹さんの名前が入ってる。忘れちゃいけないね」';topic='宛先のない手紙と消された名簿';banter='ミナ「帰ったら、妹に何を話そう」
リナ「ガルドが階段で転びかけた話」
ガルド「そこは俺が皆を守った話だろう」
テオ「両方書けば、正確な記録になるよ」'},
@{title='第3章 盾の向こう側';speaker='ガルド（戦士）';portrait='ally_warrior';boss='三十階の守り手は、ガルドの名を呼んだ。「まだ、その盾を持っているのか」声は、かつての副隊長と同じだった。倒れた鎧の奥から、偽造された退却命令が見つかる。';reveal='「俺が門を開けたんだ。村人を逃がすはずだった。向こうに待っていたのは、塔の使いだった」ガルドは盾を下ろした。「知らなかった、で済ませたくない。今度は、俺の目で道を選ぶ」';gald='「命令を守るのは得意だった。自分で選ぶのは……まだ怖い」ガルドは先の扉を見る。「間違えたら止めてくれ。黙って従う仲間には、なりたくない」';mina='「ガルドのこと、許せない人もいると思う」ミナは静かに言う。「でも、罪を思い出すためだけに、ここへ来たんじゃない。まだ助けられる人がいる」';rina='「あんたの盾、門みたいだね。閉めれば守れる。開ければ逃がせる」リナは盾を軽く叩く。「どっちが正しいか、毎回違う。だから一緒に考えるんでしょ」';theo='「偽の命令には、学院の印がある。僕の父が勤めていた場所だ」テオは紙を畳む。「関係ないと言うのは簡単だ。調べる。僕にも、確かめる責任がある」';topic='偽りの命令と、選び直す勇気';banter='ガルド「俺が先に扉を開ける」
リナ「相談してからって言ったばかり！」
ガルド「……そうだった。右と左、どっちだ？」
ミナ「聞いてくれたことが、うれしいよ」'},
@{title='第4章 森が覚えていた歌';speaker='リナ（弓使い）';portrait='ally_archer';boss='四十階の壁に、リナの故郷の樹紋が浮かぶ。守護者が放った光の中に、燃えたはずの森が見えた。「この歌……母さんが、帰り道で歌ってた」';reveal='塔に封じられた森の記憶から、生き残った人々の姿が見えた。地上の谷に隠れて暮らしている。「全部なくなったわけじゃなかった」リナは目をこする。「帰る場所、まだ探していいんだ」';gald='「森を焼いた命令にも、王都の印がある。俺の知らない戦いが、まだあるんだな」ガルドは弓弦を張るリナを見る。「知るのが怖くても、目をそらさない」';mina='「リナは、寂しい時ほどよく笑うんだね」ミナは水筒を渡す。「私の前では、うまい冗談を考えなくてもいいよ。黙って座ってても、隣にいるから」';rina='「母さんに、外の世界を見たいって言って喧嘩した。最後の言葉が、それ」リナは葉を握る。「会えたら謝る。ついでに、外にもいい人がいたって教える」';theo='「森の歌は、地図なんだ。旋律の高低が谷の形と一致する」テオは楽しそうに説明しかけ、声を落とす。「……ごめん。これは、リナの家族の歌だったね」';topic='故郷の歌と、生き残った森の人々';banter='リナ「森に帰ったら、木登りを教えてあげる」
テオ「落下の危険について先に――」
ガルド「下で受け止める。登ってこい」
ミナ「私はお昼ごはんを用意するね」'},
@{title='第5章 星の代償';speaker='テオ（魔法使い）';portrait='ally_mage';boss='五十階の装置には、テオの父の署名が刻まれていた。『星守計画――人の記憶を燃料として夜を支える』。テオは読めなくなったように、口を閉じる。';reveal='世界を照らす星は、塔が人々から奪った記憶で灯っていた。「父は世界を救おうとした。でも、そのために誰かを忘れさせた」テオは杖を握る。「正しい計算が、正しい答えとは限らないんだ」';gald='「世界を守るため、だそうだ。俺が聞かされていた言葉と同じだな」ガルドはテオの横に座る。「父親の代わりに謝るな。お前が今、何をするかを聞かせてくれ」';mina='「星を見るのが好きだった。妹と、名前をつけて遊んだの」ミナは天井を見上げる。「あの明かりに誰かの悲しみが混ざっていても、救う方法まで嫌いになりたくない」';rina='「星を消したら、地上の人も困る。だからって、人を燃やし続けるのも嫌」リナは息を吐く。「面倒な問題だね。簡単な答えに、飛びつかないでよ」';theo='「僕も研究を手伝った。燃料の欄を疑わずに、効率を上げたんだ」テオは図面を見せる。「この式を壊せるのは、仕組みを知っている僕だ。逃げずに、書き直したい」';topic='記憶を燃やす星守装置';banter='テオ「答えが三つあって、どれにも欠点がある」
リナ「じゃあ、四つ目を作ろう」
ガルド「時間は俺が稼ぐ」
ミナ「足りないものは、みんなで持ち寄ろう」'},
@{title='第6章 旅人ハルの正体';speaker='ハル（旅人）';portrait='guide';boss='六十階で、守護者は旅人と同じ声で語った。「ここで引き返せば、失ったものを返してやろう」勝利の後、ハルが姿を現す。「私は初代の星守だ。塔の底で、もうひとりの私が待っている」';reveal='ハルは自分の優しさを切り離し、塔の外へ送り出していた。本体は記憶を守るため、奪い続ける怪物となった。「私を倒すだけでは星は消える。君たちが、別の仕組みを選ばなければならない」';gald='「都合のいい話ばかりする奴は信用しない。ハルも、俺もな」ガルドは剣を収める。「でも、今から本当のことを話すなら聞く。間違ったまま終わる必要はない」';mina='「ハルさんを憎めば、楽になるのかな」ミナは首を振る。「奪ったものは返してほしい。でも、傷つけるだけでは、妹の記憶は戻らない」';rina='「引き返せば森を返す、だって。ちょっと揺れた」リナは正直に笑う。「でも、あんたたちと歩いたことまで消されるなら、安い取引じゃないね」';theo='「胸の欠片は、装置の鍵だった。君のお母さんが持ち出した安全装置だ」テオは欠片を見つめる。「だから、君ひとりを燃料にすれば修復できる……そんな設計、僕は認めない」';topic='星守ハルと、差し出された取引';banter='ハル「ひとりで背負う方が、決めるのは簡単だった」
ミナ「簡単でも、寂しかったでしょう」
ガルド「次は相談しろ」
リナ「約束を破ったら、私が追いかけるから」'},
@{title='第7章 名前を返す';speaker='ミナ（僧侶）';portrait='ally_priest';boss='七十階の守護者を倒すと、壁から無数の声が戻った。ミナは妹の名前を呼ぶ。返事は短い歌だった。「生きてる。谷で、お姉ちゃんを待ってる」';reveal='奪われた名前を口にすると、封じられた記憶が地上へ返る。五人は名簿を分けて読み始めた。君の母の名もあった。欠片から、あの日の声が戻る。『ひとりで世界を背負わないで』';gald='「名札を見つけた子の名前、覚えてるか」ガルドはゆっくり呼ぶ。「俺が覚えている限り、あの村は消えていない。帰ったら、皆の名前を門に刻みたい」';mina='「妹は私を忘れていなかった。私だけが、忘れかけてたんだね」ミナは手帳を閉じる。「もう手帳はいらない、とは言わないよ。大切だから、何度でも書く」';rina='「名前を呼ぶだけで帰れるなら、何度だって呼ぶよ」リナは母の名を口にする。「……あんたの名前も、私の歌に入れていい？」';theo='「記憶をひとりに集中させるから壊れる。名前を呼ぶ人が増えれば、負担を分けられる」テオの声に熱が戻る。「君のお母さんは、もう答えを知っていたのかもしれない」';topic='戻ってきた名前と母の言葉';banter='ミナ「みんなの名前、最初から言ってみよう」
ガルド「点呼か？ ガルド、いるぞ」
リナ「リナ。ちゃんと聞いてる」
テオ「テオ。そして、君。これで五人だね」'},
@{title='第8章 五人分の灯り';speaker='仲間たち';portrait='player';boss='八十階の装置が、君だけを鍵として引き寄せる。ガルドが腕をつかみ、リナが鎖を射抜く。ミナとテオが光を押し返した。「勝手にひとりで、決めるなよ」';reveal='テオは鍵を五つの光に分けた。「一度に世界を救うことはできない。でも、五人で記憶を運べば、少しずつ返せる」ミナが頷く。「遠回りでも、一緒に帰れる道を選びたい」';gald='「昔の俺なら、ひとりで残ると言った。格好よく終われるからな」ガルドは君の肩を叩く。「今は帰りたい。五人で。そのためなら、格好悪くても助けを呼ぶ」';mina='「助ける側は、助けられちゃいけない気がしてた」ミナは手を差し出す。「疲れたから、少しだけ握ってて。……こうして頼ってもいいんだね」';rina='「足が震えてる？ 私もだよ」リナは弓を持つ手を見せる。「怖くないふりは、もうやめた。怖いままでも、隣にあんたがいれば進める」';theo='「五人に分けた鍵は、ひとりでも欠けると不安定になる」テオは小さく笑う。「欠点と言えば欠点だ。でも、置いていかない理由が式になった。僕は、これが好きだ」';topic='五人に分けた鍵と、助けを求める勇気';banter='ガルド「休憩だ。反対意見は？」
テオ「賛成。計算が追いついてない」
リナ「賛成。お腹が先に反対してる」
ミナ「全員一致だね。あなたも、座って」'},
@{title='第9章 明日の約束';speaker='ガルド（戦士）';portrait='ally_warrior';boss='九十階の扉の向こうで、深淵王が待っている。ハルは最後の地図を置いた。「どの道にも代償がある。誰かに決めさせてはいけない。君たち自身の明日を選んでほしい」';reveal='世界へ少しずつ記憶を返す道。ひとりが星守を引き受ける道。塔を止め、人の手で夜を越える道。五人は違う答えを持っていた。それでも、選んだ後を一緒に支えると約束した。';gald='「帰ったら、村の門を直す。次は命令じゃなく、皆に頼まれて立つ」ガルドは君を見る。「その時、盾の傷の話を聞きに来い。今度は、最後まで話せる」';mina='「妹と朝ごはんを食べたい。それが私の、大きな願い」ミナは笑う。「世界を救う理由って、そんな小さなことでいいんだと思う」';rina='「森の谷まで案内する。迷ったら、私の歌を聞いて」リナは君の額を軽くつつく。「約束したからね。勝手に伝説になって、会えなくなるのは禁止」';theo='「父の式は、消さずに残すよ。間違いを隠したら、誰かが繰り返す」テオは新しい頁を開く。「その隣に、僕たちの式を書く。次の旅人が、選べるように」';topic='帰った後の約束と、三つの選択';banter='リナ「全部終わったら、最初の宿で集合ね」
ミナ「手紙も書こう」
ガルド「俺は文章が苦手だ。顔を見せに行く」
テオ「それがいちばん確実だね」'},
@{title='第10章 星を選び直す';speaker='深淵王アビス';portrait='boss_final';boss='百階。アビスの鎧が砕け、中から年老いたハルが現れた。「世界を失うのが怖かった。誰かを忘れさせれば、朝が来ると思った」その手には、最初に奪った人の名札が握られていた。';reveal='「私を正しいことにしなくていい」ハルは五つの鍵に触れる。「ただ、私が間違えたことを覚えていてほしい。君たちは、どんな朝を選ぶ？」仲間たちは君の隣に並ぶ。誰も、答えを急がせなかった。';gald='「最後の敵が人なら、斬りづらくなるか？ なるさ」ガルドは頷く。「それでいい。斬るかどうか考えられる人間のまま、ここまで来たんだから」';mina='「ハルさんが奪った人の名前も、返してあげたい」ミナは手帳を開く。「許すかどうかは、その人たちが決めること。私たちは、声を届けよう」';rina='「ここまで来たら、格好いい言葉が浮かぶと思ってた」リナは笑う。「でも、言いたいのはひとつ。帰ろう。途中で喧嘩しても、五人で帰ろう」';theo='「完璧な結末は、計算できなかった」テオは杖を持ち直す。「だから何も選ばない、とは言わない。選んだ後で直せる余地を、残しておこう」';topic='アビスの告白と、選び直す朝';banter='ガルド「準備はいいか」
リナ「最初の階でも聞いたね」
ミナ「あの時より、ちゃんと答えられるよ」
テオ「準備万端じゃない。でも、一緒に行ける」'}
)
$nodes = [System.Collections.Generic.List[object]]::new()
function Add-Node($id,$speaker,$portrait,$chapter,$text,$choices) { $nodes.Add(@{id=$id;speaker=$speaker;portrait=$portrait;chapter=$chapter;text=$text;choices=@($choices)}) }
function C($text,$next,$effect='') { return @{text=$text;next=$next;effect=$effect} }
Add-Node 'start' '語り手' 'player' '序章 星の消えた夜' '昨夜、空から星がひとつ消えた。今朝、村から母の名前が消えた。誰に尋ねても、君の母を覚えていない。胸に残った青い欠片だけが温かい。忘れられた人々の声を探し、君は星の塔の麓へ来た。' @((C '欠片を握り、塔へ向かう' 'adventure_start'))
Add-Node 'adventure_start' 'ハル（旅人）' 'guide' '序章 星の消えた夜' '「塔は、なくしたものを返すこともある。だが、ひとりで登るな」ハルの後ろに、傷のある盾を持つ戦士、手帳を抱えた僧侶、葉を髪に挿した弓使い、眼鏡の魔法使いが立っていた。「君は、どうやって進みたい？」' @((C '先頭に立って、皆を守りたい' 'brave_choice' 'stat_type=attack|bravery+2|honor+1'),(C '相談しながら、慎重に進みたい' 'careful_choice' 'stat_type=defense|cunning+2|bravery-1'),(C '塔の仕組みを、魔法で解き明かしたい' 'magic_choice' 'stat_type=magic|compassion+1|cunning+1'))
Add-Node 'brave_choice' 'ガルド（戦士）' 'ally_warrior' '序章 五人の旅立ち' '「頼もしいな。でも、先頭で倒れたら守れない。危なくなったら俺の盾の後ろに来い」ガルドは笑った。「俺はガルド。取り戻したい名前がある。お前となら、先へ進めそうだ」' @((C '背中は任せる、と答える' 'ready_for_adventure'))
Add-Node 'careful_choice' 'リナ（弓使い）' 'ally_archer' '序章 五人の旅立ち' '「いいね。焦って飛び込む人の袖を引くの、疲れるから」リナは弓を背負う。「私はリナ。森の行方を探してる。慎重なのと臆病なのは違うよ。道は、私が見つける」' @((C '道を一緒に探そう、と答える' 'ready_for_adventure'))
Add-Node 'magic_choice' 'テオ（魔法使い）' 'ally_mage' '序章 五人の旅立ち' '「僕も仕組みを知りたい。学院では、塔の研究記録が急に消されたんだ」テオは眼鏡を直した。「僕はテオ。知らないことは、知らないと言うよ。その代わり、一緒に考えてほしい」' @((C '分からないことから始めよう、と答える' 'ready_for_adventure'))
Add-Node 'ready_for_adventure' 'ミナ（僧侶）' 'ally_priest' '序章 五人の旅立ち' '「私はミナ。妹を探しているの。生きてるのかも、まだ分からないけれど」ミナは手帳に五人の名前を書いた。「塔では、忘れることがあるんだって。だから、まず皆の名前を覚えよう」' @((C '四人の名前を、声に出して呼ぶ' 'soul_vote'))
Add-Node 'soul_vote' '仲間たち' 'player' '序章 五人の旅立ち' 'ガルドは盾を上げ、リナは先の道を指す。ミナが君の袖を直し、テオは欠片の光を記録した。君が何を信じるかは、これからの選択に残っていく。最初の一歩を、どんな気持ちで踏み出す？' @((C '忘れられた人を、ひとりずつ助けたい' $null 'morality+3|compassion+3|honor+2'),(C '何としても、母の名前を取り戻したい' $null 'greed+2|cunning+2|bravery+1'),(C '誰も置いていかず、五人で帰りたい' $null 'compassion+2|bravery+2|morality+1|greed-1'))
$characters = @(
@{key='gald';speaker='ガルド（戦士）';portrait='ally_warrior';kind='話してくれてありがとう。一緒に背負おう';ask='何があったのか、もう少し聞かせて';hard='これから何をするかを、一緒に考えよう';yes='「……ありがとう。盾だけ持ってりゃいいと思ってたが、荷物を分けてもいいんだな」ガルドは肩の力を抜く。「お前も抱え込みそうになったら、俺に言え」';inquire='「うまく話せないかもしれん。それでも、最後まで聞いてくれ」ガルドは剣を鞘に戻した。戦う時より慎重に、次の言葉を選ぶ。';resolve='「そうだな。後悔だけじゃ、人は守れない」ガルドは頷く。「まずは目の前の扉だ。次は、何も確かめずに開けたりしない」';extra='ガルドは先へ出かけた足を止め、皆の位置を確かめた。「先頭だけが前を向いていても駄目だな。今日はお前の歩幅に合わせる」'},
@{key='mina';speaker='ミナ（僧侶）';portrait='ally_priest';kind='無理に笑わなくていい。隣にいるよ';ask='君が覚えていることを、聞かせてほしい';hard='帰ったら、まず何をしたい？';yes='「ありがとう。安心したら、少し泣きそう」ミナは手帳を胸に抱いた。「あなたが疲れた時も、同じ言葉を返したい。忘れないように、覚えておくね」';inquire='「小さなことばかりだよ。好きなパンの匂いとか、眠る前の声とか」ミナは笑う。「でも、小さいから消していい記憶なんて、ないと思う」';resolve='「誰かのため、だけじゃなくていいの？」ミナは少し考えた。「それなら、皆とゆっくり食事をしたい。帰ったら、私の好きな料理も作っていいかな」';extra='ミナが歩く速さを落とした。「遠くの声ばかり探して、隣の人の声を聞き逃したくないな。あなた、今は大丈夫？」'},
@{key='rina';speaker='リナ（弓使い）';portrait='ally_archer';kind='冗談のあとに隠した本音も、聞きたい';ask='君なら、どんな道を選ぶ？';hard='帰り道の案内も、君に頼みたい';yes='「見抜かれたか。気まずいなあ」リナは笑い、それから少し黙った。「でも、ちゃんと聞く人がいるなら、もう少し話してもいいかな」';inquire='「安全な道だけ探すわけじゃないよ。戻れる道を覚えておくの」リナは床に印をつける。「前へ進むのと、帰れなくなるのは別だからね」';resolve='「それ、約束だからね」リナが指を差し出した。「迷ったら歌うよ。格好悪くてもいいから、聞こえたら返事して。ちゃんと迎えに行く」';extra='リナは角を曲がる前に、振り返って手を振った。「ついてきてる？ 数えるよ。ひとり、ふたり……よし、五人。少しでも減ったら、引き返すから」'},
@{key='theo';speaker='テオ（魔法使い）';portrait='ally_mage';kind='答えが出なくても、君と考えたい';ask='その考えを、僕にも分かるように教えて';hard='間違いがあったら、一緒に直していこう';yes='「答えを急がなくても、隣にいてくれるんだね」テオは眼鏡を外した。「じゃあ、分からないところから話すよ。格好悪いけど、本当のことだから」';inquire='「いいよ。難しい言葉でごまかすのは、説明できていない証拠だ」テオは紙に五つの点を描く。「まず、僕たち五人から考えてみよう」';resolve='「間違いを消すより、直した跡を残そう」テオは図面に新しい線を引く。「後から来る人が、同じ場所で立ち止まらずに済むように」';extra='テオが図面を閉じた。「計算している間、皆の顔を見ていなかった。今は記録を休むよ。見落としたくないものが、紙の外にもあるから」'}
)
foreach ($chapterIndex in 0..9) {
 $ch = $chapters[$chapterIndex]; $bossFloor = ($chapterIndex+1)*10
 Add-Node "post_boss_$bossFloor" $ch.speaker $ch.portrait $ch.title $ch.boss @((C 'その言葉の続きを聞く' "reveal_$bossFloor"))
 if ($bossFloor -eq 100) {
  Add-Node "reveal_$bossFloor" 'ハル（星守）' 'guide' $ch.title $ch.reveal @((C '五人で記憶を分け合い、少しずつ世界へ返す' 'ending_restore_scene' 'compassion+5|honor+3|story_flag=ending_restore'),(C '星守を引き受け、地上の朝を守る' 'ending_guardian_scene' 'bravery+5|honor+4|story_flag=ending_guardian'),(C '塔を止め、人の手で夜を越える道を選ぶ' 'ending_freedom_scene' 'cunning+4|morality+3|story_flag=ending_freedom'))
 } else {
  Add-Node "reveal_$bossFloor" '仲間たち' $ch.portrait $ch.title $ch.reveal @((C '仲間の気持ちを聞き、一緒に進む' $null 'compassion+2|honor+1'),(C '分かったことを記録し、次の道を考える' $null 'cunning+2|morality+1'),(C '必ず帰ると約束して、次へ進む' $null 'bravery+2|honor+1'))
 }
 foreach ($offset in 0..9) {
  $floor = $chapterIndex*10+$offset+1; $id = "explore_$floor"
  if ($offset -lt 8) {
   $char = $characters[$offset % 4]
   $text = if ($offset -lt 4) { $ch[$char.key] } else { "${floor}階。" + $ch.topic + 'を手がかりに、五人は奥へ進む。' + $char.extra }
   Add-Node $id $char.speaker $char.portrait $ch.title $text @((C $char.kind "${id}_warm" "compassion+2|honor+1|story_flag=bond_$($char.key)"),(C $char.ask "${id}_ask" 'cunning+2|compassion+1'),(C $char.hard "${id}_resolve" 'bravery+2|honor+1'))
   Add-Node "${id}_warm" $char.speaker $char.portrait $ch.title $char.yes @((C 'その言葉を覚えて、歩き出す' $null))
   Add-Node "${id}_ask" $char.speaker $char.portrait $ch.title $char.inquire @((C '話を聞き、歩き出す' $null))
   Add-Node "${id}_resolve" $char.speaker $char.portrait $ch.title $char.resolve @((C 'うなずいて、歩き出す' $null))
  } else {
   $text = if ($offset -eq 8) { $ch.banter } else { '次の扉の前で、五人は足を止めた。' + $ch.topic + 'のことが、胸に残っている。' + "`n" + 'ガルド「盾は俺が持つ。気持ちまで隠す必要はないぞ」' + "`n" + 'ミナ「言っておきたいことがあれば、今、聞かせて」' }
   Add-Node $id '仲間たち' 'player' $ch.title $text @((C '五人で帰る約束を、もう一度確かめる' "${id}_reply" 'compassion+2|honor+2'),(C '怖さも話して、気持ちを分け合う' "${id}_reply" 'compassion+3|morality+1'),(C '帰った後の楽しみを決める' "${id}_reply" 'bravery+2|cunning+1'))
   Add-Node "${id}_reply" '仲間たち' 'player' $ch.title 'リナ「よし。帰り道までが冒険だからね」ガルドが頷き、ミナは手帳に小さな印をつけた。テオが皆の顔を見て笑う。五人の足音が、今度は同じ速さで重なった。' @((C '皆と進む' $null))
  }
 }
}
Add-Node 'ending_restore_scene' '仲間たち' 'player' '終章 帰る名前' '五つの鍵が、記憶を少しずつ地上へ運ぶ。ミナの妹から届く歌に、リナが故郷の旋律を重ねた。ガルドは名札を胸にしまい、テオは新しい式を書き留める。欠片から母の声がする。『おかえり』。君は、四人を振り返った。' @((C '「ただいま」と答えて、五人で地上へ帰る' '__ENDING__'))
Add-Node 'ending_guardian_scene' 'ミナ（僧侶）' 'ally_priest' '終章 消えない約束' '君は星守の席につく。ガルドは盾を、リナは帰り道の歌を、テオは修復の図面を残した。ミナは五人の名前を書いた手帳を開く。「忘れないよ。助けを呼ぶ時は、私たちの名前を呼んで」塔の窓に、四つの小さな灯りが帰っていく。' @((C '再会を約束し、世界の朝を迎える' '__ENDING__'))
Add-Node 'ending_freedom_scene' 'テオ（魔法使い）' 'ally_mage' '終章 人の灯り' '塔の星が消え、地上に長い夜が訪れた。けれど、人々は互いの名前を呼び、窓に灯りをともす。ガルドは道を守り、ミナは人々を迎え、リナは谷への道を歌い、テオは奪わずに灯す魔法を教えた。君の母の名は、村の人々の口に戻っていた。' @((C '小さな灯りを持ち、五人で新しい道を歩く' '__ENDING__'))
@{story_paths=@($nodes.ToArray())} | ConvertTo-Json -Depth 12 | Set-Content UnityRPG/Assets/Resources/Data/story.json -Encoding utf8
Write-Output ("Story nodes: " + $nodes.Count)
